		const { seq, publication } = receipt;
		const stored = tx.get("SELECT a.sha256,c.bytes,a.retain_until FROM artifacts a JOIN artifact_contents c USING(artifact_id) WHERE a.artifact_id=? AND a.run_id=? AND c.node_run_id=? AND c.file_name=?", [
			publication.artifact_id,
			row.run_id,
			row.node_run_id,
			rule.file_name
		]);
