			secret: deps.secret,
			registry: deps.registry,
			runner: deps.runner,
			policy: {
				allow: [command],
				declaredPolicy: "pure"
			},
			allowedTools: [command],
			nodeRunId: p.nodeRunId,
			attempt: p.attempt,
			executorAgentId: "standalone:" + p.nodeRunId,
			lease,
			nowAt,
			clock: deps.runtime.clock,
			standalone: { signal: deps.cancelSignal }
