function failControlDispatch(deps, p, row, reason, code) {
	try {
		return inTx(deps.db, (tx) => {
			const current = loadNodeRun(tx, row.node_run_id);
			if (![
				"leased",
				"dispatched",
				"started"
			].includes(current.status)) return {
				kind: "already_moved",
				currentStatus: current.status
			};
			applyTransition(tx, deps.secret, {
				nodeRunId: row.node_run_id,
				from: [
					"leased",
					"dispatched",
					"started"
				],
				to: "failed",
				ruleId: "M-48",
				attempt: current.attempt,
				expectedRevision: current.revision,
				now: p.now,
				patch: {
					lease_id: null,
					lease_expires_at: null,
					executor_session_id: null,
					executor_agent_id: null,
					wait_started_at: null,
					side_effect_policy: "pure",
					side_effect_verified_none: 1
				},
				context: {
					hasToolCall: false,
					cancelResult: null,
					hangReason: null,
					sideEffectVerifiedNone: true
				}
			});
			appendNodeRunEvent(tx, deps.secret, row.node_run_id, "dispatch.failed", {
				reason,
				error_code: code
			});
			return { kind: "applied" };
		});
	} catch (err) {
		const current = currentStatusOf(deps, row.node_run_id);
		if (current !== null && ![
			"leased",
			"dispatched",
			"started"
		].includes(current)) return {
			kind: "already_moved",
			currentStatus: current
		};
		return {
			kind: "storage_error",
			error: err,
			persistedStatus: current === null ? "unknown" : current
		};
	}
}
